  constructor(
    private formBuilder: FormBuilder,
    public route: ActivatedRoute,
    private cdr: ChangeDetectorRef,
    private apiContactService: ApiContactService,
    @Inject(DOCUMENT) private document: Document,
    public translationService: TranslationService,
    @Inject(PLATFORM_ID) private platformId: Object
  ) {
    this.isBrowser = isPlatformBrowser(this.platformId);

    this.addCareerForm = this.formBuilder.group({
      firstname: ['', Validators.required],
      email: ['', [Validators.required, Validators.email, Validators.pattern('^[a-z0-9._%+-]+@[a-z0-9.-]+\\.[a-z]{2,4}$')]],
      countryCode: ['+971'],
      message: ['', Validators.required],
      // phone: ['', Validators.required]
      phone: ['', [Validators.required, Validators.pattern(/^[0-9]{7,14}$/)]]
    });
    // this.selectedSub = this.route.snapshot.paramMap.get('id');
  }
ngAfterViewInit(): void {
		if (!this.isBrowser) return;

		const service = history.state?.service;

		if (service) {
			this.selectedSub = service;
			this.applyInitialSubjectState();
		} else {
			this.resetSubjectSelection();
		}

		window.addEventListener('message', this.calendlyListener);
		this.observeCalendlySection();
	}
