  ngOnInit(): void {
    this.addSchema();
    this.addBreadcrumbSchema();
  }
  addSchema() {
    const script = this.document.createElement("script");
    script.type = "application/ld+json";
    script.id = "contact-webpage-schema";
    script.textContent = JSON.stringify({
      "@context": "https://schema.org",
      "@type": "WebPage",
      "name": "Contact",
      "description": "Ready to create something unforgettable? Let's talk.",
      "url": "https://www.pixtar.ae/contact"
    });

    this.document.head.appendChild(script);
  }
  addBreadcrumbSchema() {
    const existingScript = this.document.getElementById("breadcrumb-schema-contact");
    if (existingScript) return;

    const script = this.document.createElement("script");
    script.type = "application/ld+json";
    script.id = "breadcrumb-schema-contact";

    script.textContent = JSON.stringify({
      "@context": "https://schema.org",
      "@type": "BreadcrumbList",
      "itemListElement": [
        {
          "@type": "ListItem",
          "position": 1,
          "name": "Home",
          "item": "https://www.pixtar.ae/"
        },
        {
          "@type": "ListItem",
          "position": 2,
          "name": "Contact",
          "item": "https://www.pixtar.ae/contact"
        }
      ]
    });

    this.document.head.appendChild(script);
  }
  ngOnDestroy(): void {
    this.calendlyObserver?.disconnect();

    if (this.isBrowser) {
      window.removeEventListener('message', this.calendlyListener);
    }
  }

  private applyInitialSubjectState(): void {
    const map: Record<string, () => void> = {
      branding: () => this.setSubjectState('branding', true),
      website: () => this.setSubjectState('website', true),
      graphics: () => this.setSubjectState('graphics', true),
      eCommerce: () => this.setSubjectState('eCommerce', true),
      seo: () => this.setSubjectState('seo', true)
    };

    map[this.selectedSub ?? '']?.();
  }

  private setSubjectState(selector: string, active: boolean): void {

    this.document.querySelectorAll(`.${selector}`).forEach((el) => el.classList.toggle('active', active));

    switch (selector) {
      case 'website':
        this.isWebsitesel = active;
        break;
      case 'branding':
        this.isBrandingsel = active;
        break;
      case 'graphics':
        this.isGraphicsel = active;
        break;
      case 'eCommerce':
        this.isEcommerce = active;
        break;
      case 'seo':
        this.isSeosel = active;
        break;
    }
  }

  public hasError = (controlName: string, errorName: string) => {
    return this.getControl(controlName)?.hasError(errorName) ?? false;
  };

  getErrorMessage(controlName: string): string {
    const control = this.getControl(controlName);
    const isArabic = this.translationService.currentLang() === 'ar';

    if (!control || !control.invalid || !(control.touched || this.submitted)) {
      return '';
    }

    if (control.hasError('required')) {
      switch (controlName) {
        case 'name':
          return isArabic ? 'الاسم مطلوب.' : 'Name is required.';
        case 'email':
          return isArabic ? 'البريد الإلكتروني مطلوب.' : 'Email is required.';
        case 'phone':
          return isArabic ? 'رقم الهاتف مطلوب.' : 'Phone number is required.';
        case 'message':
          return isArabic ? 'الرسالة مطلوبة.' : 'Comments are required.';
      }
    }

    if (controlName === 'email' && (control.hasError('email') || control.hasError('pattern'))) {
      return isArabic
        ? 'يرجى إدخال بريد إلكتروني صحيح.'
        : 'Please enter a valid email address.';
    }

    if (controlName === 'phone' && control.hasError('pattern')) {
      return isArabic
        ? 'يرجى إدخال رقم هاتف صحيح.'
        : 'Please enter a valid phone number.';
    }

    return isArabic ? 'هذا الحقل غير صالح.' : 'This field is invalid.';
  }
