  onSubmit(): void {
    this.submitted = true;
    this.submitErrorMessage = '';
    this.submitSuccessMessage = '';
    this.addCareerForm.markAllAsTouched();
    this.addCareerForm.updateValueAndValidity();
    this.subject = this.getSelectedSubjects();

    if (this.addCareerForm.invalid) {
      return;
    }

    if (this.subject.length < 1) {
      this.subjectError = true;
      return;
    }

    this.subjectError = false;

    const formValue = this.addCareerForm.getRawValue();
    const payload = {
      firstname: (formValue.firstname ?? '').trim(),
      email: (formValue.email ?? '').trim(),
      phone: `${formValue.countryCode ?? ''}${String(formValue.phone ?? '').trim()}`,
      message: (formValue.message ?? '').trim(),
      subject: this.subject.join(',')
    };

    this.isSubmitting = true;
    this.apiContactService.addContact(payload).subscribe({
      next: (response: any) => {
        if (response?.body?.code === 200) {
          this.submitSuccessMessage = response.body.message || 'Your message has been sent successfully.';
          setTimeout(() => {
            this.submitSuccessMessage = '';
            this.cdr.markForCheck();
          }, 3000);
          this.error = {};
          this.addCareerForm.reset({
            firstname: '',
            email: '',
            countryCode: '+971',
            phone: '',
            message: ''
          });
          this.resetSubjectSelection();
          this.submitted = false;
        } else {
          this.submitErrorMessage = response?.body?.message || 'Something went wrong. Please try again.';
        }
        this.isSubmitting = false;
        this.cdr.markForCheck();
      },
      error: (error: any) => {
        this.error = error;
        this.submitErrorMessage = error?.error?.message || 'Something went wrong. Please try again.';
        this.isSubmitting = false;
        this.cdr.markForCheck();
      }
    });
  }
  selectSub(type: string) {
    const selector = type;
    const isActive = this.isBrowser
      ? this.document.querySelector(`.${selector}`)?.classList.contains('active')
      : false;
    this.setSubjectState(selector, !isActive);
    this.subjectError = false;
  }

  private getControl(controlName: string): AbstractControl | null {
    return this.addCareerForm.get(controlName);
  }

  private getSelectedSubjects(): string[] {
    const selectedSubjects: string[] = [];

    if (this.isBrandingsel) {
      selectedSubjects.push('Branding');
    }
    if (this.isWebsitesel) {
      selectedSubjects.push('Website');
    }
    if (this.isGraphicsel) {
      selectedSubjects.push('Graphics');
    }
    if (this.isEcommerce) {
      selectedSubjects.push('eCommerce');
    }
    if (this.isSeosel) {
      selectedSubjects.push('SEO');
    }

    return selectedSubjects;
  }

  private resetSubjectSelection(): void {
    this.subject = [];
    this.subjectError = false;
    this.isWebsitesel = false;
    this.isBrandingsel = false;
    this.isGraphicsel = false;
    this.isSeosel = false;
    this.isEnterpricesel = false;
    this.isEcommerce = false;

    if (this.isBrowser) {
      ['branding', 'website', 'graphics', 'eCommerce', 'seo'].forEach((selector) => {
        this.document.querySelectorAll(`.${selector}`).forEach((el) => el.classList.remove('active'));
      });
    }
  }

  retryCalendlyLoad(): void {
    void this.loadCalendlyWidget();
  }

  private observeCalendlySection(): void {
    if (!this.calendlyUrl || !this.calendlySection) {
      return;
    }

    if (!('IntersectionObserver' in window)) {
      void this.loadCalendlyWidget();
      return;
    }

    this.calendlyObserver = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          this.calendlyObserver?.disconnect();
          void this.loadCalendlyWidget();
        }
      },
      { rootMargin: '250px 0px' }
    );

    this.calendlyObserver.observe(this.calendlySection.nativeElement);
  }

  private async loadCalendlyWidget(): Promise<void> {
    if (
      !this.isBrowser ||
      !this.calendlyUrl ||
      !this.calendlyContainer ||
      this.calendlyInitialized ||
      this.calendlyStatus === 'loading'
    ) {
      return;
    }

    this.calendlyStatus = 'loading';
    this.cdr.markForCheck();

    try {
      await Promise.all([
        this.loadCalendlyStyle(),
        this.loadCalendlyScript()
      ]);

      const calendly = window.Calendly;
      if (!calendly) {
        throw new Error('Calendly library is unavailable.');
      }

      const host = this.calendlyContainer.nativeElement;
      host.innerHTML = '';
      calendly.initInlineWidget({
        url: this.calendlyUrl,
        parentElement: host,
        resize: true
      });

      this.calendlyInitialized = true;
      this.calendlyStatus = 'ready';
    } catch (error) {
      console.error('Calendly failed to load.', error);
      this.calendlyStatus = 'error';
    }

    this.cdr.markForCheck();
  }

  private loadCalendlyStyle(): Promise<void> {
    if (ContactComponent.calendlyStylePromise) {
      return ContactComponent.calendlyStylePromise;
    }

    if (this.document.getElementById('calendly-widget-css')) {
      return Promise.resolve();
    }

    ContactComponent.calendlyStylePromise = new Promise<void>((resolve, reject) => {
      const link = this.document.createElement('link');
      link.id = 'calendly-widget-css';
      link.rel = 'stylesheet';
      link.href = 'https://assets.calendly.com/assets/external/widget.css';
      link.onload = () => resolve();
      link.onerror = () => {
        ContactComponent.calendlyStylePromise = undefined;
        link.remove();
        reject(new Error('Calendly stylesheet failed to load.'));
      };
      this.document.head.appendChild(link);
    });

    return ContactComponent.calendlyStylePromise;
  }

  private loadCalendlyScript(): Promise<void> {
    if (window.Calendly) {
      return Promise.resolve();
    }

    if (ContactComponent.calendlyScriptPromise) {
      return ContactComponent.calendlyScriptPromise;
    }

    ContactComponent.calendlyScriptPromise = new Promise<void>((resolve, reject) => {
      const script = this.document.createElement('script');
      script.id = 'calendly-widget-script';
      script.src = 'https://assets.calendly.com/assets/external/widget.js';
      script.async = true;
      script.defer = true;
      script.onload = () => resolve();
      script.onerror = () => {
        ContactComponent.calendlyScriptPromise = undefined;
        script.remove();
        reject(new Error('Calendly script failed to load.'));
      };
      this.document.body.appendChild(script);
    });

    return ContactComponent.calendlyScriptPromise;
  }

  sendCalendlyEmail() {
    let obj: any = {};
    obj['eventUri'] = this.eventURL;
    return this.apiContactService.SendCalendlyEmail(obj).subscribe(response => {
      if (response && response.body.code == 200) {
        this.submitted = true;
        // this.toastr.successToastr(response.body.message);
        if (this.isBrowser) {
          setInterval(() => {
            window.location.reload();
          }, 2000);
        }

      } else {
        // this.toastr.errorToastr("Error");
      }
    },
      error => this.error = error
    );
  }

